class Solution {
  private int[] tree;
  private int size;

  public int numOfUnplacedFruits(int[] fruits, int[] baskets) {
    int n = baskets.length;
    size = 1;
    while (size < n) size <<= 1;
    tree = new int[2 * size]; // max capacity over each segment
    for (int i = 0; i < n; i++) tree[size + i] = baskets[i];
    for (int i = size - 1; i >= 1; i--) tree[i] = Math.max(tree[2 * i], tree[2 * i + 1]);
    int unplaced = 0;
    for (int fruit : fruits) {
      if (tree[1] < fruit) {
        unplaced++;
        continue;
      }
      int node = 1;
      while (node < size) node = tree[2 * node] >= fruit ? 2 * node : 2 * node + 1; // leftmost fit
      tree[node] = 0;
      for (node >>= 1; node >= 1; node >>= 1)
        tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
    }
    return unplaced;
  }
}
